verification_tests:
from target import split_batches


def test_exact_batches():
    assert split_batches([1, 2, 3, 4], 2) == [[1, 2], [3, 4]]


def test_last_partial_batch_is_kept():
    assert split_batches([1, 2, 3], 2) == [[1, 2], [3]]


def test_no_row_is_lost():
    rows = list(range(7))
    assert [r for batch in split_batches(rows, 3) for r in batch] == rows
